import{_ as e,o,c as i,ao as a}from"./chunks/framework.Dpykwnwc.js";const p=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"api/contribute.md","filePath":"api/contribute.md","lastUpdated":null}'),n={name:"api/contribute.md"};function s(r,t,l,c,h,u){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h1><p>The code style of BMO, for human contributors and coding agents alike, is the section &quot;Code style&quot; of <a href="https://github.com/JuliaPhysics/BeamletOptics.jl/blob/master/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a> in the repository root. The <a href="https://github.com/SciML/SciMLStyle" target="_blank" rel="noreferrer">SciML Style Guide</a> is the formatting baseline. Refer to the <a href="https://github.com/SciML/ColPrac/blob/master/README.md" target="_blank" rel="noreferrer">SciML Contributors Guide</a> as well. Ideally, your contribution features:</p><ul><li><p>tests for new or changed functionality</p></li><li><p>docstrings for relevant functions</p></li><li><p>documentation and examples</p></li></ul><p>We would also love to feature your work with this package as part of the <strong>Examples</strong> section.</p><h2 id="Running-the-tests" tabindex="-1">Running the tests <a class="header-anchor" href="#Running-the-tests" aria-label="Permalink to &quot;Running the tests {#Running-the-tests}&quot;">​</a></h2><p>To run the full test suite, use <code>] test</code> in the package environment. To run a single test file standalone, run <code>julia --project=test -e &#39;using Pkg; Pkg.instantiate()&#39;</code> once, then <code>julia --project=test test/&lt;path&gt;.jl</code>. Tests live in a Pkg workspace subproject (<code>test/Project.toml</code>); new test-only dependencies are added there, not to the root <code>Project.toml</code>.</p><h2 id="Developing-BMO-with-an-assistant" tabindex="-1">Developing BMO with an assistant <a class="header-anchor" href="#Developing-BMO-with-an-assistant" aria-label="Permalink to &quot;Developing BMO with an assistant {#Developing-BMO-with-an-assistant}&quot;">​</a></h2><p>The agent skill of the <a href="/BeamletOptics.jl/stable/basics/ai_assistants#Using-BMO-with-AI-assistants">AI assistants</a> page describes how to <em>use</em> BMO. Instructions for changing the package itself (design philosophy, code conventions, tests) are in <code>AGENTS.md</code> at the root of the <a href="https://github.com/JuliaPhysics/BeamletOptics.jl" target="_blank" rel="noreferrer">repository</a>. <code>CLAUDE.md</code> and <code>GEMINI.md</code> point to it.</p><h1 id="Contributors" tabindex="-1">Contributors <a class="header-anchor" href="#Contributors" aria-label="Permalink to &quot;Contributors {#Contributors}&quot;">​</a></h1><p>The following is a list of people who have made significant contributions to the development of BMO:</p><ul><li><p>Hugo Uittenbosch</p></li><li><p>Oliver Kliebisch</p></li><li><p>Aurelius Manny</p></li></ul>',11)])])}const g=e(n,[["render",s]]);export{p as __pageData,g as default};
